"""Exact post-observation, reversible static-config cache experiment.
Cold O(config bytes), bounded by existing16MiB/4entries; warm O(1) per pool.
Never edits immutable bundles or shares Lua VM/account/authorization state.
"""
import hashlib
PARENTS = {'runtime/archive_backend/settlement_runner.py': '61c51346fc526a76816810469b6a8f82e1fe9b0a548628e0d18d9ac897421234', 'runtime/archive_backend/worker_fast.lua': '4a85d79d97599f44bc5026bad154f0f2ffbe35b024151ca327a30625716d20b4'}
OUTPUTS = {'runtime/archive_backend/settlement_runner.py': 'd83fc0dbd39d6fe593f0a49f7c6b34b30eb93abeadb37e67bcfccc03898453dc', 'runtime/archive_backend/worker_fast.lua': 'a34e00e825941793109b9870dc6237ded5490baa4d0e7e815c8712267b2ba256'}
PATCHES = {'archive_backend/settlement_runner.py': [('class _Entry:', 'LOTTERY_SOURCE_SHA = \'c439b0300d777820fe44fa5f05920fb3fdd3ac7e5ef2e619c2d1e01fcdcbfbcf\'\nLOTTERY_FINGERPRINT = \'    local source = canonical(pool)\\n    local a, b = 5381, 52711\\n    for i = 1, #source do\\n        a = (a * 33 + string.byte(source, i)) % 2147483647\\n        b = (b * 131 + string.byte(source, i)) % 2147483629\\n    end\\n    pool.revision = tostring(a) .. "-" .. tostring(b)\'\n\n\ndef _lottery_revision_source(bundle, lua):\n    """One immutable public-config calculation per cache identity, never per account.\n\n    O(config bytes) cold; O(1) per pool revision in each fresh VM. Unknown\n    historical source and any precomputation error retain the original module.\n    No authorization, account state, result, RNG or mutable Lua object is cached.\n    """\n    try:\n        original = (Path(bundle.directory) / "config/lottery_config.lua").read_bytes()\n        if hashlib.sha256(original).hexdigest() != LOTTERY_SOURCE_SHA:\n            return None\n        from .lottery_catalog import catalog_document\n        catalog = catalog_document(bundle, lua)\n        revisions = {}\n        for snapshot in catalog["catalog"]["snapshots"]:\n            for pool in [snapshot["selected_pool"], *snapshot["pools"]]:\n                identity, value = pool["id"], pool["revision"]\n                if (not isinstance(identity, str) or not re.fullmatch("[a-z][a-z0-9_]{0,95}", identity)\n                    or not isinstance(value, str) or not re.fullmatch("[0-9]{1,16}-[0-9]{1,16}", value)\n                    or identity in revisions and revisions[identity] != value):\n                    raise ValueError("lottery_static_revision_invalid")\n                revisions[identity] = value\n        if not 1 <= len(revisions) <= 64: raise ValueError("lottery_static_revision_count_invalid")\n        text = original.decode("utf8").replace("\\r\\n", "\\n")\n        if text.count(LOTTERY_FINGERPRINT) != 1: raise ValueError("lottery_static_revision_source_invalid")\n        prefix = b"local __backend_revisions=" + _literal(revisions) + b"\\n"\n        replacement = (\'    if __backend_revisions[pool.id] then\\n\'\n            \'        pool.revision=__backend_revisions[pool.id]\\n    else\\n\'\n            + LOTTERY_FINGERPRINT + \'\\n    end\')\n        return prefix + text.replace(LOTTERY_FINGERPRINT, replacement).encode("utf8")\n    except Exception:\n        logging.getLogger(__name__).warning("lottery_static_revision_fallback")\n        return None\n\n\nclass _Entry:'), ('            (self.directory / "index.lua").write_bytes', '            module = _lottery_revision_source(bundle, lua)\n            self.lottery_revision_cached = module is not None\n            if module is not None:\n                name = "backend_lottery_revision_module"\n                if name in index: raise ValueError("lottery_static_revision_reserved_key")\n                token = hashlib.sha256(name.encode("ascii")).hexdigest()\n                total += len(module)\n                if total > MAX_CONFIG_BYTES: raise ValueError("settlement_config_byte_budget")\n                (self.directory / (token + ".source.lua")).write_bytes(module)\n                index[name] = token\n            (self.directory / "index.lua").write_bytes'), ('self.source_bytes, self.tables = total, len(index)', 'self.source_bytes, self.tables = total, len(configs)')], 'archive_backend/worker_fast.lua': [('local decoder=require("core/json_decoder")', 'local revision_token=index.backend_lottery_revision_module\nif revision_token then\n    package.preload["config/lottery_config"]=assert(load(base.."/"..revision_token..".luac"))\nend\nlocal decoder=require("core/json_decoder")')]}

def transform(name, raw, reverse=False):
    target = "runtime/" + name
    before, after = (OUTPUTS, PARENTS) if reverse else (PARENTS, OUTPUTS)
    if type(raw) is not bytes or hashlib.sha256(raw).hexdigest() != before[target]:
        raise ValueError("lottery_cache_exact_parent_required")
    text = raw.decode("utf8")
    for old, new in (reversed(PATCHES[name]) if reverse else PATCHES[name]):
        left, right = (new, old) if reverse else (old, new)
        if text.count(left) != 1: raise ValueError("lottery_cache_patch_anchor_invalid")
        text = text.replace(left, right)
    result = text.encode("utf8")
    if hashlib.sha256(result).hexdigest() != after[target]: raise ValueError("lottery_cache_output_changed")
    if name.endswith(".py"): compile(result, name, "exec")
    return result
